python3 -c "
import json, yaml

with open('$FILE', 'r') as f:
    data = json.load(f)

result_yaml = data.get('result', '')
experiments = yaml.safe_load(result_yaml)

if not isinstance(experiments, list):
    # might be dict
    if isinstance(experiments, dict):
        exps = list(experiments.values()) if all(isinstance(v, dict) for v in experiments.values()) else [experiments]
    else:
        print('Unexpected format:', type(experiments))
        exit()
else:
    exps = experiments

# Status counts
from collections import Counter
status_counts = Counter(e.get('status','unknown') for e in exps)
print('=== STATUS COUNTS ===')
for s, c in sorted(status_counts.items(), key=lambda x: -x[1]):
    print(f'  {s}: {c}')
print(f'  TOTAL: {len(exps)}')

# Active experiments
print()
print('=== ACTIVE (RUNNING/QUEUED/PREPARING/ANALYZING) ===')
active_statuses = {'RUNNING', 'QUEUED', 'PREPARING', 'ANALYZING'}
for e in exps:
    if e.get('status') in active_statuses:
        hyp = (e.get('hypothesis','') or '')[:80]
        spec = e.get('spec', {}) or {}
        print(f\"  {e.get('exp_id','?')} | {e.get('status')} | server={spec.get('server','?')} | gpu={e.get('gpu','?')} | pid={e.get('pid','?')} | hyp={hyp}\")

# Recent DONE experiments
print()
print('=== 5 MOST RECENT DONE ===')
done_exps = [e for e in exps if e.get('status') == 'DONE']
done_exps.sort(key=lambda e: e.get('updated_at',''), reverse=True)
for e in done_exps[:5]:
    metrics = e.get('metrics', {}) or {}
    eval_pass = metrics.get('eval_pass_rate', 'N/A')
    eval_isr = metrics.get('eval_isr_mean', 'N/A')
    print(f\"  {e.get('exp_id','?')} | conclusion={e.get('conclusion','?')} | pass_rate={eval_pass} | isr_mean={eval_isr} | updated={e.get('updated_at','?')}\")

# Experiments with spec paths
print()
print('=== EXPERIMENTS WITH SERVER/MODEL/DATA PATHS IN SPEC ===')
for e in exps:
    spec = e.get('spec', {}) or {}
    paths = {}
    for k in ['server', 'model_path', 'model_name', 'data_path', 'checkpoint_path', 'checkpoint_source']:
        if spec.get(k):
            paths[k] = spec[k]
    # Also check top-level
    for k in ['checkpoint_path', 'log_path']:
        if e.get(k):
            paths[k] = e[k]
    if paths:
        print(f\"  {e.get('exp_id','?')} ({e.get('status','?')}): {paths}\")
"
